import{_ as a,o as n,c as s,a2 as r}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1786947182000}'),i={name:"guide/architecture.md"};function t(o,e,l,d,p,c){return n(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>NeoFlux uses a two-layer architecture that cleanly separates business logic from rendering.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  Application Layer (main thread)                     │</span></span>
<span class="line"><span>│                                                      │</span></span>
<span class="line"><span>│  ┌──────────┐  ┌──────────┐  ┌──────────────────┐   │</span></span>
<span class="line"><span>│  │ Widget   │  │ Taitank  │  │ EventLoop +      │   │</span></span>
<span class="line"><span>│  │ Tree     │→ │ Layout   │  │ Coroutines       │   │</span></span>
<span class="line"><span>│  └──────────┘  └──────────┘  └────────┬─────────┘   │</span></span>
<span class="line"><span>│                                       │              │</span></span>
<span class="line"><span>│                              RenderCommand           │</span></span>
<span class="line"><span>│                                       ▼              │</span></span>
<span class="line"><span>│  ┌──────────────────────────────────────────────┐   │</span></span>
<span class="line"><span>│  │  SPSC RingQueue (lock-free, FIFO)            │   │</span></span>
<span class="line"><span>│  └───────────────────────┬──────────────────────┘   │</span></span>
<span class="line"><span>└──────────────────────────┼──────────────────────────┘</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>┌──────────────────────────▼──────────────────────────┐</span></span>
<span class="line"><span>│  Render Layer (render thread)                       │</span></span>
<span class="line"><span>│                                                      │</span></span>
<span class="line"><span>│  ┌─────────────────┐    ┌──────────────────────┐    │</span></span>
<span class="line"><span>│  │ RenderCommand   │    │ tgfx (mobile)        │    │</span></span>
<span class="line"><span>│  │ Consumer        │───▶│ GLFW + OpenGL (desk) │    │</span></span>
<span class="line"><span>│  └─────────────────┘    └──────────────────────┘    │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="application-layer" tabindex="-1">Application Layer <a class="header-anchor" href="#application-layer" aria-label="Permalink to &quot;Application Layer&quot;">​</a></h2><p>The application layer runs on the main thread and is responsible for:</p><ul><li><strong>Widget tree management</strong>: Building, updating, and tearing down widget trees.</li><li><strong>Taitank layout</strong>: Running flexbox layout on the widget tree each frame.</li><li><strong>Input dispatch</strong>: Hit-testing and routing pointer/scroll events.</li><li><strong>Event loop</strong>: Processing events, driving coroutines, and triggering frames.</li><li><strong>Render command generation</strong>: Converting laid-out widgets into <code>RenderCommand</code> objects.</li></ul><h3 id="frame-pipeline" tabindex="-1">Frame Pipeline <a class="header-anchor" href="#frame-pipeline" aria-label="Permalink to &quot;Frame Pipeline&quot;">​</a></h3><p>Each frame in the application layer follows this sequence:</p><ol><li><strong>Poll events</strong> — GLFW input events are dispatched to the widget tree.</li><li><strong>Build dirty widgets</strong> — Widgets marked with <code>MarkNeedsBuild()</code> are rebuilt.</li><li><strong>Layout</strong> — <code>Taitank::DoLayout</code> computes widget positions and sizes.</li><li><strong>Paint</strong> — Each widget&#39;s <code>Paint()</code> method generates <code>RenderCommand</code>s.</li><li><strong>Submit</strong> — Commands are pushed to the SPSC ring queue.</li></ol><p>A frame is only processed when the <code>frame_dirty_</code> flag is set (by input events, route changes, or <code>MarkFrameDirty()</code>), reducing idle CPU usage.</p><h2 id="render-layer" tabindex="-1">Render Layer <a class="header-anchor" href="#render-layer" aria-label="Permalink to &quot;Render Layer&quot;">​</a></h2><p>The render layer runs on a dedicated thread and is responsible for:</p><ul><li><strong>Consuming commands</strong> — Pulling <code>RenderCommand</code>s from the ring queue.</li><li><strong>Drawing</strong> — Executing draw calls via tgfx (mobile) or OpenGL (desktop).</li><li><strong>Buffer swapping</strong> — Presenting the rendered frame to the screen.</li></ul><h3 id="desktop-rendering-glfw-bridge" tabindex="-1">Desktop Rendering (GLFW Bridge) <a class="header-anchor" href="#desktop-rendering-glfw-bridge" aria-label="Permalink to &quot;Desktop Rendering (GLFW Bridge)&quot;">​</a></h3><p>On desktop platforms, NeoFlux uses GLFW for window management and OpenGL 3.3 for rendering. The <code>GlfwBridge</code> class wraps GLFW calls and provides:</p><ul><li>Window creation and resizing</li><li>Mouse/keyboard input callbacks</li><li>OpenGL context management</li><li>Framebuffer size queries</li></ul><h3 id="mobile-rendering-tgfx" tabindex="-1">Mobile Rendering (tgfx) <a class="header-anchor" href="#mobile-rendering-tgfx" aria-label="Permalink to &quot;Mobile Rendering (tgfx)&quot;">​</a></h3><p>On mobile platforms, NeoFlux uses <a href="https://github.com/Tencent/tgfx" target="_blank" rel="noreferrer">tgfx</a> for rendering. tgfx provides a unified 2D graphics API that backs onto the platform&#39;s native graphics API (Vulkan/Metal/GLES).</p><h2 id="spsc-ring-queue" tabindex="-1">SPSC Ring Queue <a class="header-anchor" href="#spsc-ring-queue" aria-label="Permalink to &quot;SPSC Ring Queue&quot;">​</a></h2><p>Communication between layers uses a <strong>single-producer, single-consumer</strong> lock-free ring queue:</p><ul><li><strong>Producer</strong>: Application layer (main thread)</li><li><strong>Consumer</strong>: Render layer (render thread)</li><li><strong>Capacity</strong>: Configurable via <code>--render_queue_capacity</code> (default 2048)</li><li><strong>Elements</strong>: <code>RenderCommand</code> union (draw rect, draw text, clip, transform)</li></ul><p>The queue uses cache-line-aligned head/tail counters and <code>std::construct_at</code> / <code>std::destroy_at</code> for safe element construction, supporting non-trivially copyable types like <code>std::string</code>.</p><h2 id="thread-safety" tabindex="-1">Thread Safety <a class="header-anchor" href="#thread-safety" aria-label="Permalink to &quot;Thread Safety&quot;">​</a></h2><ul><li>The widget tree is only accessed from the main thread.</li><li>The render queue is the only shared data structure.</li><li><code>pressed_widget_</code> uses <code>std::weak_ptr</code> to avoid dangling references across frames.</li><li><code>frame_dirty_</code> is an <code>std::atomic&lt;bool&gt;</code> for lock-free dirty flag checks.</li></ul>`,25)])])}const h=a(i,[["render",t]]);export{u as __pageData,h as default};
